cypress_script:
describe('Slider Control Tests', () => {
  beforeEach(() => {
    cy.visit('https://demoqa.com/slider');
  });

  it('should update the slider value correctly', () => {
    cy.get('#slider').invoke('val', 75).trigger('input');
    cy.get('#sliderValue').should('have.value', '75');
  });

  it('should not allow slider to exceed maximum value', () => {
    cy.get('#slider').invoke('val', 150).trigger('input');
    cy.get('#sliderValue').should('have.value', '150');
    cy.get('#slider').invoke('val').should('not.be.greaterThan', 100);
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Slider Control Tests', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
  });

  test('should update the slider value correctly', async ({ page }) => {
    await page.locator('#slider').evaluate(slider => slider.value = 75);
    await page.locator('#slider').dispatchEvent('input');
    const sliderValue = await page.locator('#sliderValue').inputValue();
    expect(sliderValue).toBe('75');
  });

  test('should not allow slider to exceed maximum value', async ({ page }) => {
    await page.locator('#slider').evaluate(slider => slider.value = 150);
    await page.locator('#slider').dispatchEvent('input');
    const sliderValue = await page.locator('#sliderValue').inputValue();
    expect(sliderValue).toBe('150');
    const sliderVal = await page.locator('#slider').inputValue();
    expect(sliderVal).not.toBeGreaterThan('100');
  });
});
